//! Generates `ember.d.ts`, the TypeScript declarations for the `ember` global.
//!
//! Every command in the registry gets an entry, so `ember.call` and
//! `ember.bindKey` are checked against the commands that really exist, with
//! their documentation shown on hover.

use ember_core::{Command, Editor};

const HEADER: &str = "\
// Generated by Ember from its command registry. Ember rewrites this file each
// time it starts, so edit init.ts rather than this file.
//
// It declares the `ember` global for every .ts file. Each file is a module of
// its own (tsconfig.json sets moduleDetection to force), as Ember runs each
// file in its own scope.

export {};

declare global {
";

/// Everything in the namespace that does not depend on the registry.
const API: &str = r##"
  type CommandName = keyof Commands;

  const definedCommand: unique symbol;
  /** The name of a command defined by a script, as returned by defineCommand. */
  type DefinedCommand = string & { readonly [definedCommand]: true };

  /** How the minibuffer reads a parameter when the command runs from a key or M-x. */
  type ParamKind = "string" | "file" | "buffer" | "command" | "keys" | "variable" | "face";

  interface Param {
    name: string;
    /** Defaults to "string". A "keys" parameter is passed in Emacs notation, such as "C-x C-f". */
    kind?: ParamKind;
    /** The minibuffer prompt. Defaults to the name followed by ": ". */
    prompt?: string;
  }

  interface CommandDefinition {
    /** Lowercase words joined by dashes, as in Emacs: "insert-date". */
    name: string;
    /** The first line is a one-line summary. Shown by describe-command (C-h f). */
    doc?: string;
    /** Read from the minibuffer, in order, when the command runs from a key or M-x. */
    params?: Param[];
    /** Receives one string per parameter. Throw an Error to fail with its message. */
    run: (...args: string[]) => void;
  }

  /**
   * Define a command, or replace the command with the same name.
   * Returns the name, which bindKey and call accept before this file is regenerated.
   */
  function defineCommand(definition: CommandDefinition): DefinedCommand;
  /**
   * Bind a key sequence in Emacs notation, such as "C-c d", to a command, in
   * the global keymap or a named one such as "text-mode-map".
   */
  function bindKey(keys: string, command: CommandName | DefinedCommand, keymap?: string): void;
  /** Run a command with its arguments. Throws if the command fails. */
  function call<N extends CommandName | DefinedCommand>(
    name: N,
    ...args: N extends CommandName ? Commands[N] : string[]
  ): void;
  /** Show a message in the echo area. */
  function message(text: string): void;
  /** Insert text at point in the current buffer, leaving point after it. */
  function insert(text: string): void;
  /** Point, as a character offset from the start of the buffer, counting from 0. */
  function point(): number;
  /** Move point to a character offset. */
  function gotoChar(position: number): void;
  /** The text of the current buffer, or of the range from start up to end. */
  function bufferText(start?: number, end?: number): string;
  /** Delete the text from start up to end and return it. */
  function deleteRegion(start: number, end: number): string;
  /** The name of the current buffer. */
  function bufferName(): string;
  /** The mark, or undefined if it is not set. */
  function mark(): number | undefined;

  /**
   * A prefix argument, in the forms Emacs uses: null when none was given, a
   * number typed as digits (M-5, C-u 1 2), "-" for a minus sign alone (C--),
   * or a one-element array for plain C-u: [4], or [16] for C-u C-u.
   */
  type PrefixArg = null | number | "-" | [number];
  /** The prefix argument the running command was given (Emacs's current-prefix-arg). */
  function prefixArg(): PrefixArg;
  /**
   * A prefix argument as a count, as Emacs's prefix-numeric-value gives it:
   * 1 for none, -1 for "-", and n for n or [n]. Defaults to the running
   * command's argument.
   */
  function prefixNumericValue(arg?: PrefixArg): number;
  /**
   * Give the next command a prefix argument, as C-u does (Emacs's prefix-arg).
   * A command that leaves one does not count as the last command.
   */
  function setPrefixArg(arg: PrefixArg): void;
  /** The key that ran the current command, in Emacs notation such as "M-5" (Emacs's last-command-event). */
  function lastKey(): string | undefined;
  /**
   * Bind keys for the next key sequence only, ahead of every other keymap
   * (Emacs's set-transient-map). Prefix commands use it so that more digits
   * continue the argument.
   */
  function setTransientMap(bindings: { [keys: string]: CommandName | DefinedCommand }): void;

  /**
   * The kill `n` entries back from the one yanked last, moving the yank
   * pointer there (Emacs's current-kill). 0, the default, is what C-y would
   * insert now; M-y asks for 1, the kill before it.
   */
  function currentKill(n?: number): string;
  /** The command that ran before this one (Emacs's last-command). */
  function lastCommand(): string | undefined;
  /**
   * Make the running command count as another one afterwards (Emacs's
   * this-command). yank-pop sets "yank", so that M-y can follow M-y.
   */
  function setThisCommand(name: CommandName | DefinedCommand): void;
  /** Put the mark at a position without activating the region, or remove it with null. */
  function setMark(position: number | null): void;
  /**
   * Run the last command again, with the same arguments and key, and with
   * `arg` as its prefix argument if given (Emacs's last-repeatable-command).
   */
  function repeatLastCommand(arg?: PrefixArg): void;
  /** Start recording typed keys into a keyboard macro (Emacs's start-kbd-macro). */
  function startKbdMacro(): void;
  /** Finish the keyboard macro, leaving out the keys that ended it (Emacs's end-kbd-macro). */
  function endKbdMacro(): void;
  /**
   * Type the last keyboard macro `count` times, 1 by default, or until an
   * error if `count` is 0. The first error stops it and is thrown.
   */
  function callLastKbdMacro(count?: number): void;
  /** Whether a keyboard macro is being recorded. */
  function definingKbdMacro(): boolean;
  /** Whether a keyboard macro is running. */
  function executingKbdMacro(): boolean;

  /** A variable's value: what a variable can hold. */
  type Value = null | boolean | number | string | Value[];
  type VariableName = keyof Variables;
  type HookName = keyof Hooks;

  interface VariableDefinition {
    /** Lowercase words joined by dashes, as in Emacs: "fill-column". */
    name: string;
    /** Shown by describe-variable (C-h v). */
    doc?: string;
    /** The starting global value. A variable that is already defined keeps its value, as Emacs's defvar does. */
    value?: Value;
    /** Whether setting it gives the current buffer its own value (Emacs's defvar-local). */
    local?: boolean;
  }

  /** Define a documented variable (Emacs's defvar). */
  function defineVariable(definition: VariableDefinition): void;
  /** The value in the current buffer, or undefined if the variable is not defined. */
  function variable(name: VariableName | (string & {})): Value | undefined;
  /**
   * Set a variable (Emacs's setq): the current buffer's own value if it has
   * one or the variable is buffer-local, otherwise the global value.
   */
  function setVariable(name: VariableName | (string & {}), value: Value): void;
  /** The global value, which buffers without their own value see. */
  function defaultValue(name: VariableName | (string & {})): Value | undefined;
  /** Set the global value. */
  function setDefault(name: VariableName | (string & {}), value: Value): void;
  /** Give the current buffer its own value, starting from the one it sees now. */
  function makeLocalVariable(name: VariableName | (string & {})): void;
  /** Remove the current buffer's own value, so it sees the global one again. */
  function killLocalVariable(name: VariableName | (string & {})): void;
  /** Whether the current buffer has its own value. */
  function isLocalVariable(name: VariableName | (string & {})): boolean;
  function variableDocumentation(name: VariableName | (string & {})): string | undefined;
  /** The file that defined a variable, if a script did. */
  function variableSource(name: VariableName | (string & {})): string | undefined;
  /** Whether a variable is a hook. A hook's value is the names of its functions. */
  function isHook(name: string): boolean;
  /** Remove all of the current buffer's own values, hooks and keymap, as a new major mode does first. */
  function killAllLocalVariables(): void;

  /** Define a documented hook. */
  function defineHook(name: string, doc?: string): void;
  /**
   * Add a function to a hook, first in line (Emacs's add-hook). With `local`,
   * only for the current buffer; those run before the global ones.
   */
  function addHook(hook: HookName | (string & {}), run: () => void, options?: { local?: boolean }): void;
  /** Remove a function from a hook, passing the same function. */
  function removeHook(hook: HookName | (string & {}), run: () => void, options?: { local?: boolean }): void;
  /** Run a hook's functions. */
  function runHooks(hook: HookName | (string & {})): void;

  /** Define a named keymap; keys it does not bind are looked up in the parent. */
  function defineKeymap(name: string, parent?: string | null): void;
  /** Make a named keymap the current buffer's local map, the major mode's keymap. */
  function useLocalMap(name: string | null): void;

  interface MajorModeDefinition {
    /** The command that turns the mode on, such as "text-mode". */
    name: string;
    /** What the mode line shows, such as "Text". */
    modeName: string;
    /** The mode it is built on, which is set up first (Emacs's define-derived-mode). */
    parent?: CommandName | DefinedCommand | null;
    doc?: string;
    /** Keys for the mode's keymap, NAME-map, whose parent is the parent mode's keymap. */
    bindings?: { [keys: string]: CommandName | DefinedCommand };
    /** Runs after the buffer's own variables are cleared and the parent modes are set up, before the hooks. */
    setup?: () => void;
  }

  /**
   * Define a major mode. Turning it on clears the buffer's own variables, sets
   * up the parent modes and then this one, and runs the mode hooks, parent's
   * first, then after-change-major-mode-hook.
   */
  function defineMajorMode(definition: MajorModeDefinition): DefinedCommand;

  interface MinorModeDefinition {
    /** The command that turns it on and off, and the variable that says whether it is on. */
    name: string;
    /** What the mode line shows while it is on, with a leading space: " Ovwrt". */
    lighter?: string;
    doc?: string;
    /** Whether it applies to every buffer rather than one at a time. */
    global?: boolean;
    /** Keys for the mode's keymap, NAME-map, which is used while the mode is on. */
    bindings?: { [keys: string]: CommandName | DefinedCommand };
    /** Runs after the variable changes, before the mode's hooks. */
    onChange?: (enabled: boolean) => void;
  }

  /** Define a minor mode (Emacs's define-minor-mode). */
  function defineMinorMode(definition: MinorModeDefinition): DefinedCommand;
  /** The minor modes on in the current buffer. */
  function enabledMinorModes(): string[];

  /** A command's documentation, or undefined if there is no such command. */
  function documentation(name: CommandName | DefinedCommand | (string & {})): string | undefined;
  /** The file that defined a command, if a script did. */
  function commandSource(name: CommandName | DefinedCommand | (string & {})): string | undefined;
  /** Show text in the read-only *Help* buffer. */
  function showHelp(text: string): void;
  /** The file the current buffer visits, if any. */
  function bufferFileName(): string | undefined;
  function commandExists(name: string): boolean;
  /**
   * The command that is running (Emacs's this-command). In pre-command-hook,
   * the command about to run; setThisCommand changes which one runs.
   */
  function thisCommand(): string | undefined;
  /** Whether the running command was started by keys or M-x rather than called from code. */
  function calledInteractively(): boolean;
  /** Whether the region is active: shown, and what region commands act on (Emacs's region-active-p). */
  function regionActive(): boolean;

  type FaceName = keyof Faces;
  /** A face's own attributes. Colours are palette names, such as "accent" or "muted", or "#rrggbb" and "#rrggbbaa". */
  interface FaceAttributes {
    foreground?: string;
    background?: string;
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    strike?: boolean;
    /** A face to take the attributes this one does not set from. */
    inherit?: FaceName | (string & {});
  }
  interface FaceDefinition {
    /** Lowercase words joined by dashes, ending in -face for faces of a mode: "outline-1". */
    name: string;
    doc?: string;
    /** Attributes for both light and dark backgrounds. */
    attributes?: FaceAttributes;
    /** What changes on a dark background. */
    dark?: FaceAttributes;
    /** What changes on a light background. */
    light?: FaceAttributes;
  }
  /** Define a face (Emacs's defface). A face that exists keeps its attributes, which may be customised. */
  function defineFace(definition: FaceDefinition): void;
  /** Change some of a face's attributes, for both backgrounds or one (Emacs's set-face-attribute). */
  function setFaceAttribute(
    name: FaceName | (string & {}),
    attributes: FaceAttributes,
    options?: { background?: "both" | "dark" | "light" },
  ): void;
  /** A face's attributes with what it inherits filled in, for a dark background unless told otherwise. */
  function faceAttributes(name: FaceName | (string & {}), options?: { dark?: boolean }): FaceAttributes;
  /** A face's documentation and own attributes, or undefined if there is no such face. */
  function faceInfo(name: FaceName | (string & {})):
    | { doc: string; source?: string; attributes: FaceAttributes; dark: FaceAttributes; light: FaceAttributes }
    | undefined;

  /**
   * Split a window, the selected one by default, in two (Emacs's
   * split-window): the new window goes below it or to its right and shows
   * the same buffer at the same place. Returns the new window.
   */
  function splitWindow(window?: number, side?: "below" | "right"): number;
  /** Delete a window, the selected one by default, giving its space to its neighbour. */
  function deleteWindow(window?: number): void;
  /** Make a window the selected one, whose buffer commands act on. */
  function selectWindow(window: number): void;
  function selectedWindow(): number;
  /** The windows in cyclic order, left to right and top to bottom, as other-window visits them. */
  function windowList(): number[];
  /** The name of the buffer a window shows, the selected one by default. */
  function windowBuffer(window?: number): string | undefined;

  /** The languages Ember has tree-sitter grammars for. */
  function treesitLanguages(): string[];
  function treesitLanguageAvailable(language: string): boolean;
  /**
   * Parse the current buffer with a tree-sitter grammar and highlight it from
   * then on (Emacs's treesit-parser-create). A major mode's setup calls this;
   * changing the major mode removes it.
   */
  function treesitParserCreate(language: string): void;
  function treesitParserDelete(): void;
  /** The current buffer's tree-sitter language, if it has one. */
  function treesitLanguage(): string | undefined;
  /** The smallest named syntax node at a position: its type, such as "function_item", and its range. */
  function treesitNodeAt(position: number): { type: string; start: number; end: number } | undefined;

  /**
   * Set a text property on the characters from start up to end (Emacs's
   * put-text-property). "face" names a face or a list of faces, earlier ones
   * winning; "invisible" hides text, as buffer-invisibility-spec says.
   */
  function putTextProperty(start: number, end: number, name: string, value: Value): void;
  function removeTextProperty(start: number, end: number, name: string): void;
  /** The text properties of the character at a position. */
  function textPropertiesAt(position: number): { [name: string]: Value };
  function getTextProperty(position: number, name: string): Value | undefined;
  /** A property from the highest priority overlay that has it, otherwise from the text (Emacs's get-char-property). */
  function charProperty(position: number, name: string): Value | undefined;
  /** The next position where text properties change, if any. */
  function nextPropertyChange(position: number): number | undefined;
  /** The next position where text properties or overlays change. */
  function nextCharPropertyChange(position: number): number;

  /**
   * Lay an overlay over the text from start up to end, with properties such
   * as "face", "invisible", "priority" (higher wins) and "evaporate" (deleted
   * when it becomes empty). Its ends move with edits. Returns its id.
   */
  function makeOverlay(start: number, end: number, properties?: { [name: string]: Value }): number;
  function overlayPut(overlay: number, name: string, value: Value): void;
  function overlayGet(overlay: number, name: string): Value | undefined;
  function overlayStart(overlay: number): number | undefined;
  function overlayEnd(overlay: number): number | undefined;
  function moveOverlay(overlay: number, start: number, end: number): void;
  function deleteOverlay(overlay: number): void;
  /** Overlays overlapping the range, and empty ones inside it. */
  function overlaysIn(start: number, end: number): number[];
  /** Overlays covering the character at a position. */
  function overlaysAt(position: number): number[];

  /** Whether the character at a position is hidden. */
  function invisibleAt(position: number): boolean;
  /** How many lines the buffer has, counting the empty line after a final newline. */
  function lineCount(): number;
  /** The line, counting from 0, that a position is on. */
  function lineOf(position: number): number;
  /** The position where a line starts. */
  function lineStart(line: number): number;
  /** The position where a line ends, before its newline. */
  function lineEnd(line: number): number;
  /** A line's text, without its newline. */
  function lineText(line: number): string;
  /**
   * How many characters the buffer has. Positions count characters, while
   * JavaScript string indices count UTF-16 units, which differ for emoji and
   * other characters outside the Basic Multilingual Plane; work with lines
   * and positions from these functions rather than indices into bufferText().
   */
  function bufferSize(): number;
  /**
   * Make text whose invisible property is `name` hidden in this buffer
   * (Emacs's add-to-invisibility-spec); with `ellipsis`, shown as "...".
   */
  function addToInvisibilitySpec(name: string, options?: { ellipsis?: boolean }): void;
  function removeFromInvisibilitySpec(name: string): void;
}

var console: {
  /** Show values in the echo area, separated by spaces. */
  log(...values: unknown[]): void;
};
"##;

/// TypeScript declarations for the `ember` global and every command the editor has now.
pub fn type_definitions(ed: &Editor) -> String {
    let mut out = String::new();
    out += "namespace ember {\n";
    out += "  /** Every command, with the arguments it takes in order. */\n";
    out += "  interface Commands {\n";
    for command in ed.commands() {
        out += &doc_comment(command, "    ");
        let params: Vec<String> = command
            .params
            .iter()
            .enumerate()
            .map(|(i, p)| format!("{}: string", label(&p.name, i)))
            .collect();
        out += &format!("    \"{}\": [{}];\n", escape(&command.name), params.join(", "));
    }
    out += "  }\n\n";
    out += "  /** Every variable, with its documentation. */\n";
    out += "  interface Variables {\n";
    for var in ed.variables().filter(|v| !v.hook) {
        out += &variable_comment(&var.doc, var.source.as_deref(), "    ");
        out += &format!("    \"{}\": Value;\n", escape(&var.name));
    }
    out += "  }\n\n";
    out += "  /** Every face, with its documentation. */\n";
    out += "  interface Faces {\n";
    for face in ed.faces() {
        out += &variable_comment(&face.doc, face.source.as_deref(), "    ");
        out += &format!("    \"{}\": FaceAttributes;\n", escape(&face.name));
    }
    out += "  }\n\n";
    out += "  /** Every hook, with its documentation. */\n";
    out += "  interface Hooks {\n";
    for var in ed.variables().filter(|v| v.hook) {
        out += &variable_comment(&var.doc, var.source.as_deref(), "    ");
        out += &format!("    \"{}\": Value;\n", escape(&var.name));
    }
    out += "  }\n";
    out += API;
    // Everything above sits inside `declare global`.
    let mut file = String::from(HEADER);
    for line in out.lines() {
        if line.is_empty() {
            file.push('\n');
        } else {
            file += &format!("  {line}\n");
        }
    }
    file += "}\n";
    file
}

fn doc_comment(command: &Command, indent: &str) -> String {
    let mut lines: Vec<String> = command.doc.lines().map(|l| l.replace("*/", "*\\/")).collect();
    let keys_line = command
        .params
        .iter()
        .map(|p| format!("@param {} {}", p.name, p.kind.describe()))
        .collect::<Vec<_>>();
    if !keys_line.is_empty() {
        lines.push(String::new());
        lines.extend(keys_line);
    }
    if let Some(source) = &command.source {
        lines.push(String::new());
        lines.push(format!("Defined in {source}."));
    }
    let mut out = format!("{indent}/**\n");
    for line in lines {
        if line.is_empty() {
            out += &format!("{indent} *\n");
        } else {
            out += &format!("{indent} * {line}\n");
        }
    }
    out + &format!("{indent} */\n")
}

fn variable_comment(doc: &str, source: Option<&str>, indent: &str) -> String {
    let mut lines: Vec<String> = doc.lines().map(|l| l.replace("*/", "*\\/")).collect();
    if let Some(source) = source {
        lines.push(String::new());
        lines.push(format!("Defined in {source}."));
    }
    if lines.iter().all(|l| l.is_empty()) {
        return String::new();
    }
    let mut out = format!("{indent}/**\n");
    for line in lines {
        if line.is_empty() {
            out += &format!("{indent} *\n");
        } else {
            out += &format!("{indent} * {line}\n");
        }
    }
    out + &format!("{indent} */\n")
}

/// A tuple label for a parameter: the name in camelCase if that is a valid
/// identifier, otherwise `argN`.
fn label(name: &str, index: usize) -> String {
    let mut parts = name.split(['-', '_', ' ']).filter(|p| !p.is_empty());
    let mut ident = parts.next().unwrap_or("").to_string();
    for part in parts {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            ident.extend(first.to_uppercase());
            ident.push_str(chars.as_str());
        }
    }
    let valid = ident.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && ident.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if valid { ident } else { format!("arg{index}") }
}

fn escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lists_commands_with_parameters_and_docs() {
        let ed = Editor::new();
        let dts = type_definitions(&ed);
        assert!(dts.contains("    \"find-file\": [file: string];\n"), "{dts}");
        assert!(dts.contains("    \"forward-char\": [];\n"));
        assert!(dts.contains(" * Visit a file in a buffer.\n"));
        assert!(dts.contains(" * @param file file name\n"));
    }

    #[test]
    fn param_kinds_are_all_declared() {
        for kind in ember_core::ParamKind::ALL {
            assert!(API.contains(&format!("\"{}\"", kind.name())), "{} is missing from ParamKind", kind.name());
        }
    }

    #[test]
    fn labels_are_identifiers() {
        assert_eq!(label("file", 0), "file");
        assert_eq!(label("buffer-name", 0), "bufferName");
        assert_eq!(label("2nd", 1), "arg1");
        assert_eq!(label("", 2), "arg2");
    }
}
